import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

class TimesheetLineTests(unittest.TestCase):
    def test_busiest_first_with_count_and_hours(self):
        shifts = [
            Shift("Odell", "wed", Span(600, 720)),
            Shift("Brisa", "mon", Span(540, 1020)),
            Shift("Brisa", "tue", Span(540, 780)),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 12.0 hours",
                "Odell: 1 shift, 2.0 hours",
            ],
        )

    def test_ties_keep_schedule_order(self):
        shifts = [
            Shift("Quill", "mon", Span(540, 600)),
            Shift("Brisa", "tue", Span(540, 600)),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Quill: 1 shift, 1.0 hours",
                "Brisa: 1 shift, 1.0 hours",
            ],
        )

    def test_hours_to_one_decimal_place(self):
        shifts = [Shift("Odell", "mon", Span(540, 560))]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Odell: 1 shift, 0.3 hours"],
        )

    def test_empty_list_is_an_error(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_is_an_error(self):
        shifts = [Shift("  ", "mon", Span(540, 600))]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
